        { speaker: "Compañera", target: "¡Eso! Y que cante Nicolás quién escogió esa canción.", translation: "That's it! And let Nicolás confess who chose that song.", pronunciation: "EH-soh. ee keh KAN-teh nee-koh-LAS KYEN es-koh-HYOH EH-sah kan-SYON", literal: "That! And that Nicolás sing who chose that song.", why: "Here cantar means confess. The joke works because truth-telling becomes another public performance." },
        { speaker: "Nicolás", target: "Listo, canto: fui yo. Ahora arranquen conmigo.", translation: "All right, I confess: it was me. Now start with me.", pronunciation: "LEES-toh, KAN-toh: fwee yo. ah-OH-rah ah-RRAN-ken kon-MEE-goh", literal: "Ready, I sing: was I. Now start with me.", why: "“Canto: fui yo” treats the confession like a musical entrance. The pause before the truth is part of the humour." }
