        { prompt: "Which sentence uses the musical meaning of cantar?", choices: ["Cantó quién rompió el vaso durante la reunión.", "El árbitro cantó penalti en el minuto final.", "Cantamos el coro cuando llegó la parte conocida."], answer: 2, tests: "literal singing versus confessing or calling" },
        { prompt: "Why is “no respondo por los gallos” funny?", choices: ["Because gallos are cracked notes, not farm animals here.", "Because karaoke bars keep roosters beside the screen.", "Because vallenato songs are always about chickens."], answer: 0, tests: "gallo as a voice crack" },
        { prompt: "Which answer best fixes “canto bueno”?", choices: ["Canto bien, aunque hoy estoy nerviosa.", "Canto bueno, aunque hoy estoy nerviosa.", "Cantar bueno, aunque hoy estoy nerviosa."], answer: 0, tests: "bien as adverb for cantar" }
