        { prompt: "¿Cuál frase usa el sentido musical de “sing”?", choices: ["He confessed who broke the glass yesterday.", "The referee called a penalty near the end.", "We sang the chorus when everyone knew it."], answer: 2, tests: "literal sing versus confess or call" },
        { prompt: "¿Por qué “voice cracks” traduce gallos aquí?", choices: ["Porque son notas quebradas, no animales de granja.", "Porque los bares guardan gallos junto a la pantalla.", "Porque todos los vallenatos hablan de gallinas."], answer: 0, tests: "voice crack as gallo vocal" },
        { prompt: "¿Cuál corrige mejor “I sing good”?", choices: ["I sing well, although I'm nervous today.", "I sing good, although I'm nervous today.", "I singing well, although I'm nervous today."], answer: 0, tests: "well as adverb" }
